import sys
import math

def main():
    # Read all input
    input_data = sys.stdin.read().split()
    iterator = iter(input_data)

    try:
        t_str = next(iterator)
        t = int(t_str)
    except StopIteration:
        return

    MAX_A = 10000000

    # Precompute g values
    g = [0] * (MAX_A + 1)
    # by_g_value[v] = list of numbers x where g[x] == v
    by_g_value = [[]]  # Initially has index 0
    by_g_value[0].append(0)  # g[0] = 0

    for x in range(1, MAX_A + 1):
        mex = 0
        while True:
            # Check if index mex exists in by_g_value
            if mex >= len(by_g_value):
                # This shouldn't happen for small mex, but handle it
                # Actually, mex will be small most of the time, but let's be safe
                # We need to ensure by_g_value has this index before reading
                # But mex starts at 0 which exists. As mex grows, we might need extension.
                # Let's extend before reading if needed.
                while mex >= len(by_g_value):
                    by_g_value.append([])
                candidates = by_g_value[mex]
            else:
                candidates = by_g_value[mex]

            found = False
            for xp in candidates:
                if xp < x and math.gcd(x, xp) == 1:
                    found = True
                    break
            if found:
                mex += 1
            else:
                break
        g[x] = mex
        # Now add x to the bucket for value mex
        if mex < len(by_g_value):
            by_g_value[mex].append(x)
        else:
            by_g_value.append([])
            by_g_value[mex].append(x)

    # Process test cases
    results = []
    for _ in range(t):
        n = int(next(iterator))
        xor_sum = 0
        for _ in range(n):
            a = int(next(iterator))
            xor_sum ^= g[a]
        if xor_sum != 0:
            results.append("Alice")
        else:
            results.append("Bob")

    print('\n'.join(results))

if __name__ == "__main__":
    main()
